-- 작품 Apple Music 링크 바로잡기. 자료와 규칙은
-- seed_pipeline/curation/piece-link-audit-2026-11-09/(audit.py, build_fix.py,
-- apple-decisions.jsonl).
-- 바꿈 181곳, 지움 29곳.
-- 지금 값이 판정 때 본 값과 같을 때만 바꾸고, 그 작품의 곡 링크는 비운다
-- (새 앨범에서 다시 채움).

CREATE TEMPORARY TABLE tmp_fix_piece_apple (
    piece_id INT NOT NULL PRIMARY KEY,
    old_url VARCHAR(500) NOT NULL,
    new_url VARCHAR(500) NULL
);

UPDATE piece_parts part
JOIN tmp_fix_piece_apple fix ON fix.piece_id = part.piece_id
JOIN pieces piece ON piece.id = fix.piece_id
SET part.apple_music_url = NULL
WHERE piece.apple_music_url = fix.old_url;

UPDATE pieces piece
JOIN tmp_fix_piece_apple fix ON fix.piece_id = piece.id
SET piece.apple_music_url = fix.new_url
WHERE piece.apple_music_url = fix.old_url;

DROP TEMPORARY TABLE tmp_fix_piece_apple;
